import pytest
import dataclasses
from decimal import Decimal
from datetime import date, datetime as dt, timedelta
from app.domain import *
from app.abilities import *
from app.fakes import *
from app.logic import compute_balances

def test_no_actions_returns_zero_for_every_member():
    trip = Trip(trip_id='t0', name='T', base_currency='USD', members=(Member('a', 'A'), Member('b', 'B')), rates=(ExchangeRate('USD', Decimal('1')),), actions=(), closed=False)
    result = compute_balances(trip)
    assert result == {'a': 0, 'b': 0}

def test_equal_expense_produces_spec_example_balances():
    trip = Trip(trip_id='t1', name='T', base_currency='USD', members=(Member('a', 'A'), Member('b', 'B')), rates=(ExchangeRate('USD', Decimal('1')),), actions=(ExpenseAction(Expense(expense_id='e1', payer_id='a', amount=Decimal('1.00'), currency='USD', split_kind=SplitKind.EQUAL, entries=(SplitEntry('a', Decimal('0')), SplitEntry('b', Decimal('0'))), description='lunch', occurred_on=date(2026, 1, 1))),), closed=False)
    result = compute_balances(trip)
    assert result == {'a': 50, 'b': -50}

def test_expense_then_repaying_payment_settles_spec_example():
    trip = Trip(trip_id='t2', name='T', base_currency='USD', members=(Member('a', 'A'), Member('b', 'B')), rates=(ExchangeRate('USD', Decimal('1')),), actions=(ExpenseAction(Expense(expense_id='e1', payer_id='a', amount=Decimal('1.00'), currency='USD', split_kind=SplitKind.EQUAL, entries=(SplitEntry('a', Decimal('0')), SplitEntry('b', Decimal('0'))), description='lunch', occurred_on=date(2026, 1, 1))), PaymentAction(Payment(payment_id='p1', from_member_id='b', to_member_id='a', amount_cents=50, note='repayment', occurred_on=date(2026, 1, 2)))), closed=False)
    result = compute_balances(trip)
    assert result == {'a': 0, 'b': 0}

def test_payment_only_updates_sender_and_receiver_and_keeps_unaffected_member():
    trip = Trip(trip_id='t3', name='T', base_currency='USD', members=(Member('a', 'A'), Member('b', 'B'), Member('c', 'C')), rates=(ExchangeRate('USD', Decimal('1')),), actions=(PaymentAction(Payment(payment_id='p1', from_member_id='a', to_member_id='b', amount_cents=17, note='repayment', occurred_on=date(2026, 1, 1))),), closed=False)
    result = compute_balances(trip)
    assert result == {'a': 17, 'b': -17, 'c': 0}

def test_trip_with_no_members_returns_empty_balances():
    trip = Trip(trip_id='t4', name='T', base_currency='USD', members=(), rates=(ExchangeRate('USD', Decimal('1')),), actions=(), closed=False)
    result = compute_balances(trip)
    assert result == {}
